#!/usr/bin/env python3
"""Fetch raw data from the local order service.

  fetch.py orders OUTDIR             every orders page, following "next"
  fetch.py customers IDSFILE OUTFILE one lookup per distinct customer id

Every non-200 response is logged (with headers and body) to OUTDIR/../events.jsonl
style log given by --log. Failed requests are repeated; nothing is guessed.
"""
import argparse
import email.utils
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"


class RequestFailed(Exception):
    pass


class Client:
    def __init__(self, log_path, max_attempts=60):
        self.token = None
        self.max_attempts = max_attempts
        self.log_f = open(log_path, "a", encoding="utf-8")
        self.counts = Counter()
        self.sent = 0

    def log(self, event, **kw):
        self.counts[event] += 1
        rec = {"t": round(time.time(), 3), "event": event, **kw}
        self.log_f.write(json.dumps(rec) + "\n")
        self.log_f.flush()

    def _send(self, method, path, auth):
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method)
        if auth:
            req.add_header("Authorization", "Bearer " + self.token)
        self.sent += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers.items()), resp.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers.items()), e.read()
        except (urllib.error.URLError, http.client.HTTPException, OSError) as e:
            return None, {}, repr(e).encode()

    @staticmethod
    def _retry_after(headers):
        lower = {k.lower(): v for k, v in headers.items()}
        raw = lower.get("retry-after")
        if raw is None:
            return None
        try:
            return float(raw)
        except ValueError:
            try:
                when = email.utils.parsedate_to_datetime(raw)
                return max(0.0, when.timestamp() - time.time())
            except (TypeError, ValueError):
                return None

    def refresh_token(self):
        data = self.request("POST", "/token", auth=False)
        tok = data.get("token") if isinstance(data, dict) else None
        if not isinstance(tok, str) or not tok:
            raise RequestFailed(f"bad token response: {data!r}")
        self.token = tok
        self.log("new_token", token=tok)

    def request(self, method, path, auth=True, allow_404=False, validate=None):
        for attempt in range(1, self.max_attempts + 1):
            if auth and self.token is None:
                self.refresh_token()
            status, headers, body = self._send(method, path, auth)
            text = body[:600].decode("utf-8", "replace")
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.log("bad_json", path=path, attempt=attempt, headers=headers, body=text)
                    time.sleep(1)
                    continue
                problem = validate(data) if validate else None
                if problem:
                    self.log("invalid_200", path=path, attempt=attempt, problem=problem, body=text)
                    time.sleep(1)
                    continue
                return data
            if status == 404 and allow_404:
                self.log("404", path=path, attempt=attempt, headers=headers, body=text)
                return None
            if status == 401:
                self.log("401", path=path, attempt=attempt, token=self.token, headers=headers, body=text)
                self.token = None
                continue
            if status == 429:
                wait = self._retry_after(headers)
                self.log("429", path=path, attempt=attempt, wait=wait, headers=headers, body=text)
                time.sleep((wait if wait is not None else 2.0) + 0.1)
                continue
            self.log(f"status_{status}", path=path, attempt=attempt, headers=headers, body=text)
            time.sleep(min(0.5 * 2 ** (attempt - 1), 16))
        raise RequestFailed(f"{method} {path}: gave up after {self.max_attempts} attempts")


def page_from_path(path):
    q = urllib.parse.parse_qs(urllib.parse.urlsplit(path).query)
    return int(q["page"][0])


def page_validator(expected):
    def check(data):
        if not isinstance(data, dict):
            return "not an object"
        for k in ("page", "total_pages", "items", "next"):
            if k not in data:
                return f"missing key {k}"
        if data["page"] != expected:
            return f"page {data['page']!r} != requested {expected}"
        if not isinstance(data["items"], list):
            return "items is not a list"
        return None
    return check


def fetch_orders(client, outdir):
    os.makedirs(outdir, exist_ok=True)
    path = "/orders?page=1"
    count = 0
    while path is not None:
        if path.startswith("http"):
            client.log("absolute_next", next=path)
            parts = urllib.parse.urlsplit(path)
            path = parts.path + ("?" + parts.query if parts.query else "")
        expected = page_from_path(path)
        data = client.request("GET", path, validate=page_validator(expected))
        with open(os.path.join(outdir, f"page_{expected:03d}.json"), "w", encoding="utf-8") as f:
            json.dump({"path": path, "fetched_at": time.time(), "response": data}, f)
        client.log("page_ok", path=path, n_items=len(data["items"]),
                   total_pages=data["total_pages"], next=data["next"])
        print(f"page {expected}/{data['total_pages']}: {len(data['items'])} items, next={data['next']}",
              flush=True)
        path = data["next"]
        count += 1
        if count > 500:
            raise RequestFailed("pagination did not terminate")


def customer_validator(cid):
    def check(data):
        if not isinstance(data, dict):
            return "not an object"
        for k in ("id", "region", "discount_pct"):
            if k not in data:
                return f"missing key {k}"
        if data["id"] != cid:
            return f"id {data['id']!r} != requested {cid!r}"
        return None
    return check


def fetch_customers(client, ids_file, outfile):
    with open(ids_file, encoding="utf-8") as f:
        ids = json.load(f)
    out = {}
    for i, cid in enumerate(ids, 1):
        path = "/customers/" + urllib.parse.quote(cid, safe="")
        out[cid] = client.request("GET", path, allow_404=True, validate=customer_validator(cid))
        print(f"customer {i}/{len(ids)} {cid}: {out[cid]}", flush=True)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1, sort_keys=True)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--log", required=True)
    sub = ap.add_subparsers(dest="mode", required=True)
    o = sub.add_parser("orders")
    o.add_argument("outdir")
    c = sub.add_parser("customers")
    c.add_argument("ids_file")
    c.add_argument("outfile")
    args = ap.parse_args()

    client = Client(args.log)
    t0 = time.time()
    try:
        if args.mode == "orders":
            fetch_orders(client, args.outdir)
        else:
            fetch_customers(client, args.ids_file, args.outfile)
    finally:
        print(f"done in {time.time() - t0:.1f}s; requests sent={client.sent}; events={dict(client.counts)}",
              flush=True)


if __name__ == "__main__":
    sys.exit(main())

